from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrduSnssaiParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mnc, mcc = self.enb_ent_config['mnc'], self.enb_ent_config['mcc']

        self.set_parameter('mnc', mnc)
        self.set_parameter('mcc', mcc)
        self.set_parameter('mncLength', self.get_len_str(mnc))
        self.set_parameter('sd', self.enb_ent_config['sd'])
        self.set_parameter('sst', self.enb_ent_config['sst'])
